# 简易记事本
notes = []

def add_note():
    title = input('请输入笔记标题：')
    content = input('请输入笔记内容：')
    notes.append({'title': title, 'content': content})
    print('笔记已添加！')

def show_notes():
    for i, note in enumerate(notes, 1):
        print(f"{i}. {note['title']}: {note['content']}")

def delete_note():
    show_notes()
    index = int(input('请输入要删除的笔记编号：')) - 1
    if 0 <= index < len(notes):
        del notes[index]
        print('笔记已删除！')
    else:
        print('编号无效。')

# 主循环
while True:
    print('\n1. 添加笔记  2. 查看笔记  3. 删除笔记  4. 退出')
    choice = input('请选择操作：')
    if choice == '1':
        add_note()
    elif choice == '2':
        show_notes()
    elif choice == '3':
        delete_note()
    elif choice == '4':
        break
    else:
        print('无效选择，请重新输入。')

